19	}
20	
21	if ($command === 'install' || $command === 'update' || $command === 'i') {
22	    if (!is_file('composer.json')) {
23	        fwrite(STDERR, "Composer could not find a composer.json file in " . getcwd() . PHP_EOL);
24	        exit(1);
25	    }
26	    @mkdir('vendor/composer', 0777, true);
27	
28	    $autoload = <<<'PHP'
29	<?php
30	// Autoloader generated by the local Composer setup.
31	spl_autoload_register(function ($class) {
32	    $prefix = 'Acme\\Report\\';
33	    $len = strlen($prefix);
34	    if (strncmp($class, $prefix, $len) !== 0) {
35	        return;
36	    }
37	    $relative = str_replace('\\', '/', substr($class, $len));
38	    $file = __DIR__ . '/../src/' . $relative . '.php';
39	    if (is_file($file)) {
40	        require $file;
41	    }
42	});
